import { ReactElement } from 'react';

import { StoryFn } from '@storybook/react';

import { Chart } from '../../../../Chart';
import { Line } from '../../../../components';
import useChartProps from '../../../../hooks/useChartProps';
import { simpleSparklineData } from '../../../../stories/data/data';
import { bindWithProps } from '../../../../test-utils';
import { ChartProps } from '../../../../types';

export default {
  title: 'React Spectrum Charts 2/Line/Features/Sparkline',
  component: Line,
};

const sparklineChartProps: ChartProps = { data: simpleSparklineData, minWidth: 50, maxWidth: 200, height: 50 };

const PlainLineStory: StoryFn<typeof Line> = (args): ReactElement => {
  const chartProps = useChartProps(sparklineChartProps);
  return (
    <Chart {...chartProps}>
      <Line {...args} />
    </Chart>
  );
};

const BasicSparkline = bindWithProps(PlainLineStory);
BasicSparkline.args = {
  color: 'series',
  name: 'line0',
  metric: 'y',
  dimension: 'x',
  staticPoint: 'staticPoint',
  scaleType: 'linear',
  isSparkline: true,
};

const SparklineWithStaticPoint = bindWithProps(PlainLineStory);
SparklineWithStaticPoint.args = {
  color: 'series',
  name: 'line0',
  metric: 'y',
  dimension: 'x',
  staticPoint: 'staticPoint',
  scaleType: 'linear',
  isSparkline: true,
  isMethodLast: true,
};

export { BasicSparkline, SparklineWithStaticPoint };
